import{j as e}from"./vendor-motion-D-QS5Tde.js";import{H as i}from"./index-DTryBJkQ.js";import{N as a,F as t}from"./Footer-KawF-dDP.js";import{P as n,C as s,N as r}from"./NextProject-BUYY37sz.js";import{C as l}from"./CsNumList-Dk-YZZ5D.js";import{C as c}from"./CsCredits-DAUbZekd.js";import{C as o}from"./CsThanks-Cx9c-DN_.js";import{B as d}from"./BottomNav-BQIsGLMm.js";import"./vendor-react-P2F7fkol.js";import"./vendor-three-CMud_36L.js";function w(){return e.jsxs(e.Fragment,{children:[e.jsxs(i,{children:[e.jsx("title",{children:"UV Light Experience · Parth Pawar"}),e.jsx("meta",{name:"description",content:"Creating an immersive experience utilizing blacklights, invisible ink, and hidden messages, guiding participants through interactive spaces while subtly revealing monitoring, culminating in the revelation of a significant message on portraits."}),e.jsx("meta",{property:"og:type",content:"article"}),e.jsx("meta",{property:"og:title",content:"UV Light Installation · Parth Pawar"}),e.jsx("meta",{property:"og:description",content:"Immersive experience with blacklights, invisible ink, and hidden messages in interactive spaces."}),e.jsx("meta",{property:"og:image",content:"https://parthpawar.com/Assets/images/uv-light.jpg"})]}),e.jsx(a,{}),e.jsxs("main",{id:"main-content",className:"project-main",style:{"--project-color":"#6B46C1"},children:[e.jsx(n,{backLink:"/work",categorySlug:"installations",backLabel:"Back to Work",tags:["Installation","Experience Design","Art"],title:"UV Light Experience",subtitle:"Creating an immersive experience utilizing blacklights, invisible ink, and hidden messages",info:[{label:"Client",value:"NYU – ITP"},{label:"Scope of Work",value:"Experience Design"},{label:"Role",value:"Artist"},{label:"Duration",value:"2 Weeks"},{label:"Year",value:"2023"}],heroImage:"/Assets/Projects/UVLight/Desktop/1.jpg",heroAlt:"UV Light Experience — immersive blacklight installation with participants"}),e.jsx("section",{className:"cs-section reveal",id:"cs-background",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Background"}),e.jsx("h2",{className:"cs-display",children:"The Concept"}),e.jsxs(s,{children:[e.jsxs("ul",{className:"cs-list",children:[e.jsx("li",{children:"Creating an immersive experience using blacklights, invisible ink, UV light, paper, projectors, and hidden messages."}),e.jsx("li",{children:"Engaging participants through exploration and discovery within designated spaces."})]}),e.jsx("p",{children:"The concept began with a simple question: what happens when the things you need to see are invisible under normal conditions? UV-reactive materials offered a way to create a layered environment where participants had to actively search for meaning rather than passively receive it. The installation was designed as a journey through multiple rooms, each revealing hidden content only under blacklight."}),e.jsx("p",{children:"The thematic anchor was surveillance and visibility — the tension between being watched and being unaware of it. Participants moved through spaces that appeared ordinary under normal light but transformed under UV illumination, mirroring the way hidden systems of observation operate in everyday life. The experience was designed to provoke reflection on what we choose to reveal, what remains hidden, and who controls the light that makes things visible."})]})]})}),e.jsx("section",{className:"cs-section reveal",id:"cs-exploration",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Exploration"}),e.jsx("h2",{className:"cs-display",children:"Ideation"}),e.jsxs(s,{children:[e.jsxs("ul",{className:"cs-list",children:[e.jsx("li",{children:"Brainstorming the use of blacklights and invisible ink to create hidden messages and interactive “elevator” spaces."}),e.jsx("li",{children:"Aiming for subtle participant monitoring through hidden cameras."})]}),e.jsx("p",{children:"The ideation phase involved extensive material testing — experimenting with different brands of invisible ink, UV-reactive paints, and fluorescent tapes to determine which materials produced the most vivid and reliable results under blacklight. We tested across several UV wavelength ranges (365nm to 395nm) and discovered that ink visibility varied dramatically depending on the light source, which informed our choice of blacklight fixtures for the final installation."}),e.jsx("p",{children:"Early prototypes explored small-scale “elevator” enclosures where a single participant would enter a confined space and discover hidden messages on the walls. We iterated on the spatial design through paper mockups and cardboard prototypes at ITP, testing how different room sizes, lighting angles, and message densities affected the sense of discovery. The hidden camera concept emerged as a way to create an asymmetry of knowledge — some participants exploring while others observed — reinforcing the installation’s theme of visible and invisible layers."})]}),e.jsx("div",{className:"cs-img-full",children:e.jsx("img",{src:"/Assets/Projects/UVLight/Desktop/2.jpg",alt:"Ideation sketches, whiteboard brainstorming, and early process photos",loading:"lazy"})})]})}),e.jsx("section",{className:"cs-section reveal",id:"cs-making",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Making"}),e.jsx("h2",{className:"cs-display",children:"Process"}),e.jsxs(s,{children:[e.jsxs("ul",{className:"cs-list",children:[e.jsx("li",{children:"Setting up multiple “elevator” style spaces in rooms with blacklight-covered walls displaying hidden messages."}),e.jsx("li",{children:"Allowing participants to explore these areas before directing them to an auditorium with a live feed showing their exploration."})]}),e.jsx("p",{children:"The physical build required transforming two standard ITP classrooms into immersive UV environments. We covered windows and sealed light leaks with blackout fabric, then installed arrays of blacklight LED strips along the ceiling perimeter to ensure even UV coverage across all wall surfaces. Hidden messages were hand-painted onto the walls using invisible ink pens and UV-reactive paint, with content ranging from cryptic phrases to fragments of Van Gogh’s letters."}),e.jsx("p",{children:"The auditorium served as the observation room, where a live video feed from cameras in the UV spaces was projected on a large screen. This created a deliberate contrast: participants in the UV rooms experienced discovery and wonder, while those in the auditorium experienced the discomfort of watching others be watched. The technical setup required running long HDMI cables between rooms and calibrating the camera exposure to capture the UV-lit environment accurately, since standard camera settings tend to wash out blacklight scenes."})]})]})}),e.jsx("section",{className:"cs-section reveal",id:"cs-discovery",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Discovery"}),e.jsx("h2",{className:"cs-display",children:"Research"}),e.jsxs(s,{children:[e.jsx("p",{children:"Engaging participants in an immersive journey involving interaction with hidden elements and discovering the ‘SHOW DON’T TELL’ message displayed on various portraits."}),e.jsx("p",{children:"The research phase drew on principles from environmental psychology and immersive theatre design. We studied how installations like Meow Wolf and Punchdrunk’s “Sleep No More” guide participants through space without explicit instructions, relying instead on environmental cues, curiosity, and social dynamics. The key finding was that discovery-based experiences work best when the hidden content rewards exploration without punishing those who miss it — every participant should have a meaningful experience, even if they do not find every hidden message."}),e.jsx("p",{children:"We also researched the science of UV fluorescence to understand why certain materials glow under blacklight and others do not. This technical understanding informed our material choices and helped us predict how different surfaces — paper, fabric, skin, clothing — would behave in the UV environment. The unexpected fluorescence of everyday items like white t-shirts and teeth became part of the experience, blurring the line between intentional design and accidental discovery."})]})]})}),e.jsx("section",{className:"cs-section reveal",id:"cs-narrative",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Narrative"}),e.jsx("h2",{className:"cs-display",children:"Unfold of Act"}),e.jsx(l,{items:[e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Arrival and Grouping"})," — Participants were organized into groups of four and ushered into the first room."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"The UV Revelation"})," — Initially handed blank paper, attendees discovered hidden drawings under UV light upon entering the room. Each revealed piece contributed to a larger painting."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Projection of ‘Starry Night’"})," — As they worked on their contributions, a projector displayed Van Gogh’s mesmerizing ‘Starry Night’ video, immersing the space in the artist’s iconic masterpiece."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Completion of the Puzzle Painting"})," — After completing their individual drawings, participants placed them strategically to form a cohesive puzzle painting resembling Van Gogh’s style."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Transition to the Second Room"})," — Moving to the next room, attendees found seats furnished with pamphlets containing Van Gogh’s poetry."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Artistic Presentation"})," — At the center of the room, the performer crafted a small violin out of paper, symbolizing Van Gogh’s passion for art."]}),e.jsxs(e.Fragment,{children:[e.jsx("strong",{children:"Final Act"})," — Upon finishing the violin, the performer returned to the first room and placed the paper violin at the center of the puzzle painting."]})]})]})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Documentation"}),e.jsx("h2",{className:"cs-section-title",children:"Experience"}),e.jsxs("div",{className:"cs-img-pair",children:[e.jsx("div",{className:"cs-img",children:e.jsx("img",{src:"/Assets/Projects/UVLight/Desktop/3.jpg",alt:"Participants discovering hidden UV drawings and assembling the puzzle painting under blacklight",loading:"lazy"})}),e.jsx("div",{className:"cs-img",children:e.jsx("img",{src:"/Assets/Projects/UVLight/Desktop/4.jpg",alt:"Second room with Van Gogh pamphlets, poetry, and seated attendees",loading:"lazy"})})]})]})}),e.jsx("section",{className:"cs-section reveal",id:"cs-interaction",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Interaction"}),e.jsx("h2",{className:"cs-section-title",children:"Hidden Messages & Portraits"}),e.jsxs(s,{children:[e.jsx("p",{children:"Each participant received a portrait card with seemingly innocent questions — “How many cups of coffee have you had since the start of the program?”, “What do you enjoy most about your work?”, “How many hours of sleep do you get daily?”, “What do you enjoy about ITP?”, “Draw anything”, and “What are your weekend plans?”. Under UV light, the hidden messages and drawings were revealed on these seemingly blank surfaces."}),e.jsx("p",{children:"The portrait cards served a dual purpose. On the surface, they were a friendly icebreaker — casual questions that put participants at ease. But the hidden UV messages on each card, visible only under blacklight, reframed those innocent questions as acts of data collection. The reveal created a moment of surprise and mild discomfort: participants realized they had been willingly sharing personal information, and the hidden layer made them question what else might be recorded without their knowledge."}),e.jsx("p",{children:"This interaction mechanic was the conceptual heart of the installation. By making participants complicit in their own observation — they filled in the cards voluntarily, even enthusiastically — the piece illustrated how surveillance often operates through consent rather than coercion. The “SHOW DON’T TELL” message, revealed across the assembled portrait cards under UV light, served as both an artistic manifesto and a commentary on the hidden architectures of everyday data collection."})]})]})}),e.jsx("div",{className:"cs-slide reveal",children:e.jsx("img",{src:"/Assets/Projects/UVLight/Desktop/5.jpg",alt:"Portrait cards with hidden UV messages and the blacklight-lit stage floor",loading:"lazy"})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Environment"}),e.jsx("h2",{className:"cs-section-title",children:"The Blacklight Stage"}),e.jsx(s,{children:e.jsx("p",{children:"The main stage was transformed into a UV-reactive environment with fluorescent tape markings on the floor, colorful UV dots, and hidden text that only became visible under blacklight. Participants explored the space, discovering hidden elements as they moved through zones of visible and invisible light."})})]})}),e.jsx("div",{className:"cs-slide reveal",children:e.jsx("img",{src:"/Assets/Projects/UVLight/Desktop/6.jpg",alt:"UV-lit stage with fluorescent floor markings and participants assembling puzzle pieces",loading:"lazy"})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Engagement"}),e.jsx("h2",{className:"cs-section-title",children:"Participant Interaction"}),e.jsx(s,{children:e.jsx("p",{children:"Participants engaged deeply with the installation, examining UV-revealed messages on their cards, viewing hidden drawings through blacklight, and filling out their personal portrait cards with handwritten answers. A live camera feed in the auditorium showed the exploration happening in real-time, adding a subtle layer of monitoring to the experience."})})]})}),e.jsx("div",{className:"cs-slide reveal",children:e.jsx("img",{src:"/Assets/Projects/UVLight/Desktop/7.jpg",alt:"Close-ups of UV-revealed messages on cards and participant portraits under blacklight",loading:"lazy"})}),e.jsx("div",{className:"cs-slide reveal",children:e.jsx("img",{src:"/Assets/Projects/UVLight/Desktop/8.jpg",alt:"Participants exploring the UV space, filled-in portrait cards, and live camera feed in the auditorium",loading:"lazy"})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Team"}),e.jsx("h2",{className:"cs-display",children:"Credits"}),e.jsx(c,{credits:[{role:"Artist",name:"Parth Pawar"},{role:"Artist Collaborators",name:"Nathan, Lauren, Baiyuian"}]})]})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Capabilities"}),e.jsx("h2",{className:"cs-display",children:"Tools and Techniques"}),e.jsxs("div",{className:"cs-tags",children:[e.jsx("span",{className:"cs-tag-item",children:"Fabrication"}),e.jsx("span",{className:"cs-tag-item",children:"Research"}),e.jsx("span",{className:"cs-tag-item",children:"Interview"}),e.jsx("span",{className:"cs-tag-item",children:"Python"}),e.jsx("span",{className:"cs-tag-item",children:"Data Visualisation"}),e.jsx("span",{className:"cs-tag-item",children:"3D Printing"}),e.jsx("span",{className:"cs-tag-item",children:"Dismantling"}),e.jsx("span",{className:"cs-tag-item",children:"Sculptor"})]})]})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Contribution"}),e.jsx("h2",{className:"cs-display",children:"My Role"}),e.jsx(s,{children:e.jsx("p",{children:"My role encompasses conceptualizing and implementing the immersive experience, overseeing the setup of interactive spaces, monitoring systems, and orchestrating participant engagement to reveal the hidden message, ensuring a captivating and impactful journey for all involved."})})]})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"Reflections"}),e.jsx("h2",{className:"cs-section-title",children:"What I Learned"}),e.jsxs(s,{style:{maxWidth:"720px"},children:[e.jsx("p",{children:"The UV Light Experience was my first project where the design medium was space itself, not a screen. The key insight was that participatory installations require a careful balance between structure and freedom. Too much direction and participants feel herded; too little and they miss the hidden elements entirely. The solution was environmental cues—UV-reactive tape on the floor subtly guided movement without explicit instructions."}),e.jsx("p",{children:"The live camera feed added an unexpected layer. Participants in the auditorium watched others explore the UV rooms, creating a voyeuristic tension that reinforced the installation’s theme of hidden observation. This was not planned—it emerged from the setup. It taught me that the best design moments often come from responding to emergent behavior rather than scripting every interaction."})]})]})}),e.jsx(o,{}),e.jsx(d,{sections:[{id:"cs-background",label:"Background"},{id:"cs-exploration",label:"Exploration"},{id:"cs-making",label:"Making"},{id:"cs-discovery",label:"Discovery"},{id:"cs-narrative",label:"Narrative"},{id:"cs-interaction",label:"Interaction"}]})]}),e.jsx(r,{slug:"revolving-stage",title:"Revolving Stage",image:"/Assets/images/revolving-stage.jpg"}),e.jsx(t,{})]})}export